$(document).ready(function() {

  /*
   * Swiper JS — iDangerous
   * @link: http://idangero.us/swiper/
   * Documentation: http://idangero.us/swiper/api/#.WHX7L7bhAQ8
   * Démos: http://idangero.us/swiper/api/#.WHX7L7bhAQ8
   */
  var swiper = [];

  /*
   * Swiper appliqué sur desktop et mobile, �  l'aide de la class .js-swiper
   */
  $('.js-swiper').each(function(index) {

    var $el = $(this);

    swiper[index] = $el.swiper({
      slidesPerView: 1,
      autoplay: true,
      nextButton: '.js-swiper-control-next', // bouton "suivant"
      prevButton: '.js-swiper-control-prev', // bouton "précédent"
      pagination: '.js-swiper-pagination',   // pagination
      paginationClickable: true,
      paginationBulletRender: function (swiper, index, className) {
        return '<span class="swiper-pagination-item ' + className + '"><span class="visually-hidden">Item ' + (index + 1) + '</span></span>';
      },
      loop: true,
      a11y: true
    });

    // on cache le bouton "play" sur l'autoplay est activé par défaut sur le slider
    if (swiper[index].params.autoplaying = true) {
      $(this).find('.js-swiper-control-play').addClass('is-hidden');
    }

    // bouton pour stopper le défilement automatique
    $(this).find('.js-swiper-control-pause').on('click', function(e){
        swiper[index].stopAutoplay();
        $(this).addClass('is-hidden');
        $('.js-swiper-control-play').removeClass('is-hidden');
    });
    // bouton pour relancer le défilement automatique
    $(this).find('.js-swiper-control-play').on('click', function(e){
        swiper[index].startAutoplay();
        $(this).addClass('is-hidden');
        $('.js-swiper-control-pause').removeClass('is-hidden');
    });

  });

  /*
   * Swiper appliqué uniquement sur petit écran (<640px), �  l'aide de la class .js-m-swiper ("m" = mobile)
   */
  if (window.matchMedia("(max-width: 640px)").matches) {

    $('.js-m-swiper').each(function(index) {

      var $el = $(this);

      swiper[index] = $el.swiper({
        slidesPerView: 'auto',
        nextButton: '.js-swiper-control-next', // bouton "suivant"
        prevButton: '.js-swiper-control-prev', // bouton "précédent"
        pagination: '.js-swiper-pagination', // pagination
        paginationClickable: true,
        paginationBulletRender: function (swiper, index, className) {
          return '<span class="swiper-pagination-item ' + className + '"><span class="visually-hidden">Item ' + (index + 1) + '</span></span>';
        },
        loop: false,
        spaceBetween: 15,
        a11y: true
      });

    });

  }


  /*
   * Compteur animé au scroll
   * D'après le script : https://github.com/bfintal/Counter-Up
   */
  $('.js-counter').counterUp({
    delay: 5,
    time: 1000
  });


  /*
   * Main navigation (niveau 2)
   * Ajout d'une class "non-hover" sur tous les liens du niveau 2 sauf celui qui est survolé (afin d'appliquer un style CSS aux autres liens)
   */
  $('.subnavigation-link').hover(function() {
    $('.subnavigation-link').addClass('non-hover');
    $(this).removeClass('non-hover');
  });


  /*
   * Main navigation (niveau 2)
   * On cache le sous-menu le temps de quelques secondes pour éviter qu'il s'affiche au chargement de la page
   */
  // Visual hack to avoid CSS3 animation on window resize
  var resizeTimer;

  // Hide .js-accessible-navigation on page loading
  $('.js-nav-system__subnav').hide();

  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(function() {

    // Show .js-accessible-navigation when the page is loaded
    $('.js-nav-system__subnav').show();

  }, 50);

});

/*!
* jquery.counterup.js 1.0
*
* Copyright 2013, Benjamin Intal http://gambit.ph @bfintal
* Released under the GPL v2 License
*
* Date: Nov 26, 2013
*/
(function( $ ){
  "use strict";

  $.fn.counterUp = function( options ) {

    // Defaults
    var settings = $.extend({
        'time': 400,
        'delay': 10
    }, options);

    return this.each(function(){

        // Store the object
        var $this = $(this);
        var $settings = settings;

        var counterUpper = function() {
            var nums = [];
            var divisions = $settings.time / $settings.delay;
            var num = $this.text();
            var isComma = /[0-9]+,[0-9]+/.test(num);
            num = num.replace(/,/g, '');
            var isInt = /^[0-9]+$/.test(num);
            var isFloat = /^[0-9]+\.[0-9]+$/.test(num);
            var decimalPlaces = isFloat ? (num.split('.')[1] || []).length : 0;

            // Generate list of incremental numbers to display
            for (var i = divisions; i >= 1; i--) {

                // Preserve as int if input was int
                var newNum = parseInt(num / divisions * i);

                // Preserve float if input was float
                if (isFloat) {
                    newNum = parseFloat(num / divisions * i).toFixed(decimalPlaces);
                }

                // Preserve commas if input had commas
                if (isComma) {
                    while (/(\d+)(\d{3})/.test(newNum.toString())) {
                        newNum = newNum.toString().replace(/(\d+)(\d{3})/, '$1'+','+'$2');
                    }
                }

                nums.unshift(newNum);
            }

            $this.data('counterup-nums', nums);
            $this.text('0');

            // Updates the number until we're done
            var f = function() {
                $this.html('<span>'+$this.data('counterup-nums').shift().toString().split('').join('</span><span>')+'</span>');
                if ($this.data('counterup-nums').length) {
                    setTimeout($this.data('counterup-func'), $settings.delay);
                } else {
                    delete $this.data('counterup-nums');
                    $this.data('counterup-nums', null);
                    $this.data('counterup-func', null);
                }
            };
            $this.data('counterup-func', f);

            // Start the count up
            setTimeout($this.data('counterup-func'), $settings.delay);
        };

        // Perform counts when the element gets into view
        // $this.waypoint(counterUpper, { offset: '100%', triggerOnce: true });
        // uses jquery.inview to bind the event
        $this.on('inview', function() {
          if(!$this.data('counterUpper')) {
            $this.data('counterUpper',true); // To avoid multiple launches
            counterUpper();
          }
        });
    });

  };

})( jQuery );

/**!
 Menu déroulant pour la navigation principale

 @author: N. Hoffmann
 @link: https://github.com/nico3333fr/jquery-accessible-subnav-dropdown

 Modifié par Alsacreations
 @contributors: Jennifer Noesser
 */

$(document).ready(function() {

   /*
    * jQuery accessible and keyboard-enhanced navigation with dropdown
    * Website: http://a11y.nicolas-hoffmann.net/subnav-dropdown/
    * License MIT: https://github.com/nico3333fr/jquery-accessible-subnav-dropdown/blob/master/LICENSE
    */
   // loading expand paragraphs
   var $nav_system = $('.js-nav-system'),
       $body = $('body');
   if ($nav_system.length) { // if there is at least one :)

      // initialization
      var $nav_system_link = $('.js-nav-system__link');

      $nav_system_link.each(function(index_to_expand) {
         var $this = $(this),
             index_lisible = index_to_expand + 1,
             $subnav = $this.next('.js-nav-system__subnav');

         // if there is a subnav adjacent to the link
         if ($subnav.length === 1) {
            $subnav.attr({
               'data-visually-hidden': 'true'
            });
         }
      });

   }

   // events on main menu
   // mouse !
   $body.on('mouseenter', '.js-nav-system__item', function(event) {
         var $this = $(this),
             $subnav_link = $this.children('.js-nav-system__link'),
             $subnav = $this.children('.js-nav-system__subnav');

         $this.attr({
            'data-show-sub': 'true'
         });

         // show submenu
         if ($subnav.length === 1) {
            $subnav.attr({
               'data-visually-hidden': 'false'
            });
         }

      })
      .on('mouseleave', '.js-nav-system__item', function(event) {
         var $this = $(this),
             $subnav_link = $this.children('.js-nav-system__link'),
             $subnav = $this.children('.js-nav-system__subnav');

         $this.attr({
            'data-show-sub': 'false'
         });
         // show submenu
         if ($subnav.length === 1) {
            $subnav.attr({
               'data-visually-hidden': 'true'
            });
         }

      })
      // keyboard
      .on('focus', '.js-nav-system__link', function(event) {
         var $this = $(this),
             $parent = $this.parents('.js-nav-system'),
             $parent_item = $this.parents('.js-nav-system__item'),
             $subnav = $this.next('.js-nav-system__subnav');

         $parent_item.attr({
            'data-show-sub': 'true'
         });

         // hide other menus and show submenu activated
         $parent.find('.js-nav-system__subnav').attr({
            'data-visually-hidden': 'true'
         });

         if ($subnav.length === 1) {
            $subnav.attr({
               'data-visually-hidden': 'false'
            });
         }

      })
      .on('focusout', '.js-nav-system__link', function(event) {
         var $this = $(this),
             $parent = $this.parents('.js-nav-system'),
             $parent_item = $this.parents('.js-nav-system__item');

         $parent_item.attr({
            'data-show-sub': 'false'
         });
      })
      .on('keydown', '.js-nav-system__link', function(event) {
         var $this = $(this),
             $parent = $this.parents('.js-nav-system'),
             $parent_item = $this.parents('.js-nav-system__item'),
             $subnav = $this.next('.js-nav-system__subnav');

         // event keyboard left
         if (event.keyCode == 37) {
            // select previous nav-system__link

            // if we are on first => activate last
            if ($parent_item.is(".js-nav-system__item:first-child")) {
               $parent.find(" .js-nav-system__item:last-child ").children(".js-nav-system__link").focus();
            }
            // else activate previous
            else {
               $parent_item.prev().children(".js-nav-system__link").focus();
            }
            event.preventDefault();
         }

         // event keyboard right
         if (event.keyCode == 39) {
            // select previous nav-system__link

            // if we are on last => activate first
            if ($parent_item.is(".js-nav-system__item:last-child")) {
               $parent.find(" .js-nav-system__item:first-child ").children(".js-nav-system__link").focus();
            }
            // else activate next
            else {
               $parent_item.next().children(".js-nav-system__link").focus();
            }
            event.preventDefault();
         }

         // event keyboard bottom
         if (event.keyCode == 40) {
            // select first nav-system__subnav__link
            if ($subnav.length === 1) {
               // if submenu has been closed => reopen
               $subnav.attr({
                  'data-visually-hidden': 'false'
               });
               // and select first item
               $subnav.find(" .js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
            }
            event.preventDefault();
         }

         // event shift + tab
         if (event.shiftKey && event.keyCode == 9) {
            if ($parent_item.is(".js-nav-system__item:first-child")) {
               $subnav.attr({
                  'data-visually-hidden': 'true'
               });
            } else {

               var $prev_nav_link = $parent_item.prev('.js-nav-system__item').children(".js-nav-system__link");
                   $subnav_prev = $prev_nav_link.next('.js-nav-system__subnav');
               if ($subnav_prev.length === 1) { // hide current subnav, show previous and select last element
                  $subnav.attr({
                     'data-visually-hidden': 'true'
                  });
                  $subnav_prev.attr({
                    'data-visually-hidden': 'false'
                  });
                  $subnav_prev.find(" .js-nav-system__subnav__item:last-child ").children(".js-nav-system__subnav__link").focus();
                  event.preventDefault();
               }
            }
         }

      });

   // events on submenu item
   $body.on('keydown', '.js-nav-system__subnav__link', function(event) {
         var $this = $(this),
             $subnav = $this.parents('.js-nav-system__subnav'),
             $subnav_item = $this.parents('.js-nav-system__subnav__item'),
             $nav_link = $subnav.prev('.js-nav-system__link'),
             $nav_item = $nav_link.parents('.js-nav-system__item'),
             $nav = $nav_link.parents('.js-nav-system');

         // event keyboard bottom
         if (event.keyCode == 40) {
            // if we are on last => activate first
            if ($subnav_item.is(".js-nav-system__subnav__item:last-child")) {
               $subnav.find(".js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
            }
            // else activate next
            else {
               $subnav_item.next().children(".js-nav-system__subnav__link").focus();
            }
            event.preventDefault();
         }
         // event keyboard top
         if (event.keyCode == 38) {
            // if we are on first => activate last
            if ($subnav_item.is(".js-nav-system__subnav__item:first-child")) {
               $subnav.find(" .js-nav-system__subnav__item:last-child ").children(".js-nav-system__subnav__link").focus();
            }
            // else activate previous
            else {
               $subnav_item.prev().children(".js-nav-system__subnav__link").focus();
            }
            event.preventDefault();
         }
         // event keyboard Esc
         if (event.keyCode == 27) {
            // close the menu
            $nav_link.focus();
            $subnav.attr({
               'data-visually-hidden': 'true'
            });
            event.preventDefault();
         }
         // event keyboard right
         if (event.keyCode == 39) {
            // select next nav-system__link
            $subnav.attr({
               'data-visually-hidden': 'true'
            });

            // if we are on last => activate first and choose first item
            if ($nav_item.is(".js-nav-system__item:last-child")) {
               $next = $nav.find(" .js-nav-system__item:first-child ").children(".js-nav-system__link");
               $next.focus();
               $subnav_next = $next.next('.js-nav-system__subnav');
               if ($subnav_next.length === 1) {
                  $subnav_next.find(" .js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
               }
            }
            // else activate next
            else {
               $next = $nav_item.next().children(".js-nav-system__link");
               $next.focus();
               $subnav_next = $next.next('.js-nav-system__subnav');
               if ($subnav_next.length === 1) {
                  $subnav_next.find(" .js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
               }
            }
            event.preventDefault();
         }
         // event keyboard left
         if (event.keyCode == 37) {
            // select prev nav-system__link
            $subnav.attr({
               'data-visually-hidden': 'true'
            });

            // if we are on first => activate last and choose first item
            if ($nav_item.is(".js-nav-system__item:first-child")) {
               $prev = $nav.find(" .js-nav-system__item:last-child ").children(".js-nav-system__link");
               $prev.focus();
               $subnav_prev = $prev.next('.js-nav-system__subnav');
               if ($subnav_prev.length === 1) {
                  $subnav_prev.find(".js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
               }
            }
            // else activate prev
            else {
               $prev = $nav_item.prev().children(".js-nav-system__link");
               $prev.focus();
               $subnav_prev = $prev.next('.js-nav-system__subnav');
               if ($subnav_prev.length === 1) {
                  $subnav_prev.find(".js-nav-system__subnav__item:first-child ").children(".js-nav-system__subnav__link").focus();
               }
            }
            event.preventDefault();
         }
         // event tab
         if (event.keyCode == 9 && !event.shiftKey) { // if we are on last subnav of last item and we go forward => hide subnav
            if ($nav_item.is(".js-nav-system__item:last-child") && $subnav_item.is(".js-nav-system__subnav__item:last-child")) {
               $subnav.attr({
                  'data-visually-hidden': 'true'
               });
            }
         }

      })
      .on('focus', '.js-nav-system__subnav__link', function(event) {
         var $this = $(this),
             $subnav = $this.parents('.js-nav-system__subnav'),
             $subnav_item = $this.parents('.js-nav-system__subnav__item'),
             $nav_link = $subnav.prev('.js-nav-system__link'),
             $nav_item = $nav_link.parents('.js-nav-system__item'),
             $nav = $nav_link.parents('.js-nav-system__item');

         $nav_item.attr({
            'data-show-sub': 'true'
         });
      })
      .on('focusout', '.js-nav-system__subnav__link', function(event) {
         var $this = $(this),
             $subnav = $this.parents('.js-nav-system__subnav'),
             $subnav_item = $this.parents('.js-nav-system__subnav__item'),
             $nav_link = $subnav.prev('.js-nav-system__link'),
             $nav_item = $nav_link.parents('.js-nav-system__item'),
             $nav = $nav_link.parents('.js-nav-system__item');

         $nav_item.attr({
            'data-show-sub': 'false'
         });
      });



});

/**
 * author Christopher Blum
 *    - based on the idea of Remy Sharp, http://remysharp.com/2009/01/26/element-in-view-event-plugin/
 *    - forked from http://github.com/zuk/jquery.inview/
 */
(function (factory) {
  if (typeof define == 'function' && define.amd) {
    // AMD
    define(['jquery'], factory);
  } else if (typeof exports === 'object') {
    // Node, CommonJS
    module.exports = factory(require('jquery'));
  } else {
      // Browser globals
    factory(jQuery);
  }
}(function ($) {

  var inviewObjects = [], viewportSize, viewportOffset,
      d = document, w = window, documentElement = d.documentElement, timer;

  $.event.special.inview = {
    add: function(data) {
      inviewObjects.push({ data: data, $element: $(this), element: this });
      // Use setInterval in order to also make sure this captures elements within
      // "overflow:scroll" elements or elements that appeared in the dom tree due to
      // dom manipulation and reflow
      // old: $(window).scroll(checkInView);
      //
      // By the way, iOS (iPad, iPhone, ...) seems to not execute, or at least delays
      // intervals while the user scrolls. Therefore the inview event might fire a bit late there
      //
      // Don't waste cycles with an interval until we get at least one element that
      // has bound to the inview event.
      if (!timer && inviewObjects.length) {
         timer = setInterval(checkInView, 250);
      }
    },

    remove: function(data) {
      for (var i=0; i<inviewObjects.length; i++) {
        var inviewObject = inviewObjects[i];
        if (inviewObject.element === this && inviewObject.data.guid === data.guid) {
          inviewObjects.splice(i, 1);
          break;
        }
      }

      // Clear interval when we no longer have any elements listening
      if (!inviewObjects.length) {
         clearInterval(timer);
         timer = null;
      }
    }
  };

  function getViewportSize() {
    var mode, domObject, size = { height: w.innerHeight, width: w.innerWidth };

    // if this is correct then return it. iPad has compat Mode, so will
    // go into check clientHeight/clientWidth (which has the wrong value).
    if (!size.height) {
      mode = d.compatMode;
      if (mode || !$.support.boxModel) { // IE, Gecko
        domObject = mode === 'CSS1Compat' ?
          documentElement : // Standards
          d.body; // Quirks
        size = {
          height: domObject.clientHeight,
          width:  domObject.clientWidth
        };
      }
    }

    return size;
  }

  function getViewportOffset() {
    return {
      top:  w.pageYOffset || documentElement.scrollTop   || d.body.scrollTop,
      left: w.pageXOffset || documentElement.scrollLeft  || d.body.scrollLeft
    };
  }

  function checkInView() {
    if (!inviewObjects.length) {
      return;
    }

    var i = 0, $elements = $.map(inviewObjects, function(inviewObject) {
      var selector  = inviewObject.data.selector,
          $element  = inviewObject.$element;
      return selector ? $element.find(selector) : $element;
    });

    viewportSize   = viewportSize   || getViewportSize();
    viewportOffset = viewportOffset || getViewportOffset();

    for (; i<inviewObjects.length; i++) {
      // Ignore elements that are not in the DOM tree
      if (!$.contains(documentElement, $elements[i][0])) {
        continue;
      }

      var $element      = $($elements[i]),
          elementSize   = { height: $element[0].offsetHeight, width: $element[0].offsetWidth },
          elementOffset = $element.offset(),
          inView        = $element.data('inview');

      // Don't ask me why because I haven't figured out yet:
      // viewportOffset and viewportSize are sometimes suddenly null in Firefox 5.
      // Even though it sounds weird:
      // It seems that the execution of this function is interferred by the onresize/onscroll event
      // where viewportOffset and viewportSize are unset
      if (!viewportOffset || !viewportSize) {
        return;
      }

      if (elementOffset.top + elementSize.height > viewportOffset.top &&
          elementOffset.top < viewportOffset.top + viewportSize.height &&
          elementOffset.left + elementSize.width > viewportOffset.left &&
          elementOffset.left < viewportOffset.left + viewportSize.width) {
        if (!inView) {
          $element.data('inview', true).trigger('inview', [true]);
        }
      } else if (inView) {
        $element.data('inview', false).trigger('inview', [false]);
      }
    }
  }

  $(w).on("scroll resize scrollstop", function() {
    viewportSize = viewportOffset = null;
  });

  // IE < 9 scrolls to focused elements without firing the "scroll" event
  if (!documentElement.addEventListener && documentElement.attachEvent) {
    documentElement.attachEvent("onfocusin", function() {
      viewportOffset = null;
    });
  }
}));

/**!
 Menu Burger sur les tablettes et mobiles (< 960px)

 @contributors: Jennifer Noesser
 */

(function($) {

  $.menuBurger = function(el, options) {

    // Default settings values
    var defaults = {
      // Burger button to open/close the navigation
      burgerButton: '.js-menuburger',

      // Apply to the burger button, when it's actove
      classButtonActive: 'is-active',

      // Apply to the menu, when it's opened
      classMenuActive: 'is-opened',

      // The off canvas menu you want to open. Ex: data-target=".navigation"
      target: '.site-navigation',

      // Apply to the website content, when the menu is opened
      classOffCanvasActive: 'is-active',

      // The part of the website content you want to switch to the right side (off canvas). Ex: data-selector-off-canvas=".js-content-off-canvas"
      selectorOffCanvas: '',

      // px, should match ($tiny-screen) (scss)
      mobileMaxWidth: 960
    };

    var plugin = this;

    plugin.settings = {};

    var $element = $(el),
      element = el;

    // Plugin initialization
    plugin.init = function() {
      plugin.settings = $.extend({}, defaults, options);
      updateSettingsFromHTMLData();
      registerEvents();
    };

    // Reads plugin settings from HTML data-* attributes (camelCase)
    var updateSettingsFromHTMLData = function() {
      var data = $element.data();
      for (var dat in data) plugin.settings[dat] = data[dat];
    };

    // Set event handlers on HTML elements (private method)
    var registerEvents = function() {
      $element.off('click.menuburger').on('click.menuburger', plugin.toggleMenu);
      $(window).off('resize.menuburger').on('resize.menuburger', plugin.resetMenu);
    };

    // Plugin toggle Menu on/off (public method)
    plugin.toggleMenu = function() {
      if (window.matchMedia("(max-width: "+plugin.settings.mobileMaxWidth+"px)").matches) {
        $(plugin.settings.burgerButton).toggleClass(plugin.settings.classButtonActive);
        $(plugin.settings.target).toggleClass(plugin.settings.classMenuActive);
        $(plugin.settings.selectorOffCanvas).toggleClass(plugin.settings.classOffCanvasActive);
      }
    };

    // Disable off canvas when in desktop
    plugin.resetMenu = function() {
      if (!window.matchMedia("(max-width: "+plugin.settings.mobileMaxWidth+"px)").matches) {
        $(plugin.settings.burgerButton).removeClass(plugin.settings.classButtonActive);
        $(plugin.settings.target).removeClass(plugin.settings.classMenuActive);
        $(plugin.settings.selectorOffCanvas).removeClass(plugin.settings.classOffCanvasActive);
      }
    };

    // Initialization
    plugin.init();

  };

  $.fn.menuBurger = function(options) {

    return this.each(function() {
      if (undefined === $(this).data('menuBurger')) {
        var plugin = new $.menuBurger(this, options);
        $(this).data('menuBurger', plugin);
      }
    });

  };

  $(document).ready(function() {

    // Launch plugin on target element
    $('.js-menuburger').menuBurger();

  });


})(jQuery);

jQuery(document).ready(function($) {

  var $window = $(window);
  var $styleguideMenu = $('.sg-menu');
  var to = false;

  // Menu: fixed position when scrolling
  if($styleguideMenu.length>0) $window.on('scroll',function() {

    clearTimeout(to);
    to = setTimeout(function() {
      if($window.scrollTop()>165) {
        $styleguideMenu.addClass('is-fixed');
      } else {
        $styleguideMenu.removeClass('is-fixed');
      }
    },30);

  });

});